<?php
namespace Database\Seeders; use App\Enums\UserRole; use App\Models\{Order, User}; use Illuminate\Database\Seeder;
class DatabaseSeeder extends Seeder { public function run(): void { $this->call(RolePermissionSeeder::class); $owner=User::factory()->role(UserRole::Owner)->create(['name'=>'EEEJOKI Owner','email'=>'owner@eeejoki.test']); $admin=User::factory()->role(UserRole::Admin)->create(['name'=>'Operations Admin','email'=>'admin@eeejoki.test']); $workers=User::factory()->count(5)->role(UserRole::Worker)->create(); $customers=User::factory()->count(10)->role(UserRole::Customer)->create(); User::factory()->count(3)->role(UserRole::Affiliate)->create(); User::all()->each(fn(User $user)=>$user->assignRole($user->role->value)); Order::factory()->count(20)->recycle($customers)->create()->each(fn(Order $order)=>$order->update(['worker_id'=>$workers->random()->id])); } }
